import express, { Request, Response, NextFunction } from 'express';
import multer from 'multer';
import zlib from 'zlib';
import { pipeline } from 'stream/promises';
import { Readable, Transform } from 'stream';
import crypto from 'crypto';

interface TenantConfig {
  id: string;
  maxUploadBytes: number;
  decompressionRatio: number;
  allowedFormats: string[];
}

const tenantRegistry = new Map<string, TenantConfig>();
tenantRegistry.set('tenant-alpha', { id: 'tenant-alpha', maxUploadBytes: 10 * 1024 * 1024, decompressionRatio: 50, allowedFormats: ['gzip', 'deflate'] });
tenantRegistry.set('tenant-beta', { id: 'tenant-beta', maxUploadBytes: 5 * 1024 * 1024, decompressionRatio: 100, allowedFormats: ['gzip'] });

const app = express();
const upload = multer({ storage: multer.memoryStorage(), limits: { fileSize: 50 * 1024 * 1024 } });

function getTenantFromHeader(req: Request): TenantConfig | null {
  const tenantId = req.headers['x-tenant-id'] as string;
  if (!tenantId) return null;
  return tenantRegistry.get(tenantId) || null;
}

class DecompressionGuard extends Transform {
  private bytesWritten: number = 0;
  private readonly maxBytes: number;
  private readonly compressedSize: number;
  private readonly maxRatio: number;

  constructor(maxBytes: number, compressedSize: number, maxRatio: number) {
    super();
    this.maxBytes = maxBytes;
    this.compressedSize = compressedSize;
    this.maxRatio = maxRatio;
  }

  _transform(chunk: Buffer, encoding: string, callback: Function) {
    this.bytesWritten += chunk.length;

    // Check absolute size limit
    if (this.bytesWritten > this.maxBytes) {
      callback(new Error(`Decompression exceeded max size: ${this.maxBytes} bytes`));
      return;
    }

    // Check ratio - but only enforce after we've seen enough data
    // to avoid false positives on small files
    if (this.compressedSize > 1024) {
      const currentRatio = this.bytesWritten / this.compressedSize;
      if (currentRatio > this.maxRatio) {
        callback(new Error(`Decompression ratio ${currentRatio.toFixed(1)} exceeds limit ${this.maxRatio}`));
        return;
      }
    }

    this.push(chunk);
    callback();
  }
}

async function decompressPayload(compressedData: Buffer, tenant: TenantConfig): Promise<Buffer> {
  const chunks: Buffer[] = [];
  const inputStream = Readable.from(compressedData);
  const decompressor = zlib.createGunzip();

  const guard = new DecompressionGuard(
    tenant.maxUploadBytes * tenant.decompressionRatio,
    compressedData.length,
    tenant.decompressionRatio
  );

  const collector = new Transform({
    transform(chunk, enc, cb) {
      chunks.push(chunk);
      cb(null, chunk);
    }
  });

  await pipeline(inputStream, decompressor, guard, collector);
  return Buffer.concat(chunks);
}

function computeIntegrityHash(data: Buffer): string {
  return crypto.createHash('sha256').update(data).digest('hex');
}

app.post('/api/v1/upload/compressed', upload.single('payload'), async (req: Request, res: Response) => {
  try {
    const tenant = getTenantFromHeader(req);
    if (!tenant) {
      return res.status(401).json({ error: 'Invalid tenant' });
    }

    if (!req.file) {
      return res.status(400).json({ error: 'No file provided' });
    }

    const compressedData = req.file.buffer;

    // Validate compressed size against tenant limit
    if (compressedData.length > tenant.maxUploadBytes) {
      return res.status(413).json({ error: 'Compressed payload too large' });
    }

    const decompressed = await decompressPayload(compressedData, tenant);
    const hash = computeIntegrityHash(decompressed);

    return res.status(200).json({
      tenantId: tenant.id,
      originalSize: compressedData.length,
      decompressedSize: decompressed.length,
      hash,
      status: 'processed'
    });
  } catch (err: any) {
    if (err.message?.includes('Decompression')) {
      return res.status(413).json({ error: err.message });
    }
    return res.status(500).json({ error: 'Internal processing error' });
  }
});

export default app;
